import logging

from taf.collectors.core.factories.named_factory import NamedComponentFactory
from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.internal.portforwarding import Portforwarding

from .collector import DcapTraceCollector

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class DcapTraceCollectorFactory(Creating("local_executor", "LocalExecutor"), NamedComponentFactory):
    """
    Factory to create a DCAP trace collector.
    """

    _product_class = DcapTraceCollector
    _mandatory_parameters = {"trace"}
    _optional_parameters = {"dcap", "invalidate_bts_info_cache"}

    def __init__(self, port_forwarding=None, **kwargs):
        super(DcapTraceCollectorFactory, self).__init__(**kwargs)
        if port_forwarding is None:
            port_forwarding = Portforwarding()
        self._port_forwarding = port_forwarding

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(DcapTraceCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)

        if "dcap" in configuration:
            dcap = configuration["dcap"].copy()
        else:
            dcap = {}
        for key, value in {"host": "127.0.0.1", "port": 9443, "secure": True}.items():
            dcap.setdefault(key, value)
        resulting_arguments["dcap"] = dcap

        if "hops" in configuration:
            hops = configuration["hops"]
            remote_service = self._port_forwarding.create_remote_service(
                ip=dcap["host"],
                port=dcap["port"])

            hop_list = DcapTraceCollectorFactory._generate_hop_list(self._port_forwarding, hops)
            ssh_forwarding_branch = self._port_forwarding.create_ssh_forwarding_branch(
                hops=hop_list,
                remote_service=remote_service)
            resulting_arguments["ssh_forwarding_branch"] = ssh_forwarding_branch

    @staticmethod
    def _generate_hop_list(port_forwarding, hops):
        hops = hops.copy()
        proxy = hops.pop("proxy", None)
        hop = [port_forwarding.create_ssh_forwardable_hop(**hops)]
        return DcapTraceCollectorFactory._generate_hop_list(port_forwarding, proxy) + hop \
            if proxy else hop
